    float eh, el;
    exp_ff(__fmul_rn(2.0f, ax), &eh, &el);
    // D = exp + 1 as a *normalized* float-float. exp_ff's low word holds the whole polynomial tail (up to
    // ~1e-5), and the one-step division below assumes |dl| <= ulp(dh)/2; without this renormalization the
    // exhaustive check found 85,400 wrong results (diary, step 9).
    const float d0 = __fadd_rn(eh, 1.0f), e0 = __fadd_rn(__fsub_rn(1.0f, __fsub_rn(d0, eh)), el);  // Fast2Sum
    const float dh = __fadd_rn(d0, e0), dl = __fsub_rn(e0, __fsub_rn(dh, d0));                     // Fast2Sum
    const float q1 = __fdiv_rn(2.0f, dh);
    const float rr = __fmaf_rn(-q1, dl, __fmaf_rn(-q1, dh, 2.0f));
    const float q2 = __fdiv_rn(rr, dh);
    const float s = __fsub_rn(1.0f, q1);  // TwoSum(1, -q1)
    const float bb = __fsub_rn(s, 1.0f);
    const float e = __fadd_rn(__fsub_rn(1.0f, __fsub_rn(s, bb)), __fsub_rn(-q1, bb));
    th = s;
    tl = __fsub_rn(e, q2);
    E = __fmaf_rn(fabsf(th), EXP_REL, EXP_REL);
  }
  const float lo = __fadd_rn(th, __fsub_rn(tl, E)), hi = __fadd_rn(th, __fadd_rn(tl, E));
  if (lo != hi) return false;
  *out = copysignf(lo, x);
  return true;
}
__device__ __forceinline__ float fast_tanh(float x) {
  float y;
  return fast_tanh_try(x, &y) ? y : ref_tanh(x);
}
static void init_tanh_table() {
  float th[64], tl[64];
  for (int j = 0; j < 64; ++j) {
    const long double v = exp2l(j / 64.0L);
    th[j] = (float)v;
    tl[j] = (float)(v - (long double)th[j]);
  }
  CHECK(cudaMemcpyToSymbol(XH, th, sizeof th));
  CHECK(cudaMemcpyToSymbol(XL, tl, sizeof tl));
}


using I = int64_t;
__device__ static float rf_minmax(float a, float b, bool maximum) {  // same definition as Stage 2's minmax
  if (isnan(a) || isnan(b)) return __uint_as_float(0x7fc00000);
  if (a == b) {
    unsigned x = __float_as_uint(a), y = __float_as_uint(b);
    return __uint_as_float(maximum ? x & y : x | y);
  }
  return (maximum ? a > b : a < b) ? a : b;
}
__device__ float rf_block_max(float v) {
  __shared__ float part[32];
  for (int o = 16; o; o >>= 1) v = rf_minmax(v, __shfl_xor_sync(0xffffffffu, v, o), true);
  const int warps = (blockDim.x + 31) / 32, lane = threadIdx.x & 31, warp = threadIdx.x >> 5;
  if (lane == 0) part[warp] = v;
  __syncthreads();
  if (warp == 0) {
    v = lane < warps ? part[lane] : -INFINITY;
    for (int o = 16; o; o >>= 1) v = rf_minmax(v, __shfl_xor_sync(0xffffffffu, v, o), true);
    if (lane == 0) part[0] = v;
  }
  __syncthreads();
  v = part[0];
  __syncthreads();
  return v;
}
struct Tensor { std::vector<int64_t> shape; std::vector<float> data; };
static uint64_t rng = 0x2545F4914F6CDD1Dull;
static Tensor make(std::vector<int64_t> shape, float lo, float hi) {
  Tensor t{shape, {}};
  int64_t n = 1;
  for (auto d : shape) n *= d;
  t.data.resize(n);
  for (auto& x : t.data) { rng ^= rng << 13; rng ^= rng >> 7; rng ^= rng << 17; x = lo + (hi - lo) * (float)((rng >> 40) / 16777216.0); }
  return t;
}
typedef void (*RunCase)(FILE*, FILE*, bool);
static Tensor stage2(RunCase run, const std::vector<Tensor>& params, int rank, double* ms) {
  std::vector<char> req;
  for (auto& p : params) {
    req.insert(req.end(), (const char*)p.shape.data(), (const char*)(p.shape.data() + p.shape.size()));
    req.insert(req.end(), (const char*)p.data.data(), (const char*)(p.data.data() + p.data.size()));
  }
  FILE* in = fmemopen(req.data(), req.size(), "rb");
  char* buf = nullptr; size_t len = 0;
  FILE* out = open_memstream(&buf, &len);
  run(in, out, true);
  fclose(in); fclose(out);
  Tensor t; t.shape.resize(rank);
  memcpy(t.shape.data(), buf, rank * 8);
  int64_t n = 1;
  for (auto d : t.shape) n *= d;
  t.data.resize(n);
  memcpy(t.data.data(), buf + rank * 8, n * 4);
  memcpy(ms, buf + rank * 8 + n * 4, 8);
  free(buf);
  return t;
}
struct Dev {
  float* p = nullptr;
  explicit Dev(const std::vector<float>& h) { CHECK(cudaMalloc(&p, h.size() * 4 + 4)); CHECK(cudaMemcpy(p, h.data(), h.size() * 4, cudaMemcpyHostToDevice)); }
  explicit Dev(size_t n) { CHECK(cudaMalloc(&p, n * 4 + 4)); }
  ~Dev() { cudaFree(p); }
};
template <class F> static float median_ms(F launch, int reps = 21) {
  cudaEvent_t s, e; CHECK(cudaEventCreate(&s)); CHECK(cudaEventCreate(&e));
  launch(); CHECK(cudaDeviceSynchronize()); CHECK(cudaGetLastError());
  std::vector<float> ms(reps);
  for (int r = 0; r < reps; ++r) { CHECK(cudaEventRecord(s)); launch(); CHECK(cudaEventRecord(e)); CHECK(cudaEventSynchronize(e)); CHECK(cudaEventElapsedTime(&ms[r], s, e)); }
  std::sort(ms.begin(), ms.end());
  return ms[reps / 2];
}
static long long word_diffs(const std::vector<float>& a, const std::vector<float>& b) {
  if (a.size() != b.size()) return -1;
  long long n = 0;
  for (size_t i = 0; i < a.size(); ++i) n += memcmp(&a[i], &b[i], 4) != 0;
  return n;
}
static std::vector<float> download(const Dev& d, size_t n) {
  std::vector<float> h(n);
  CHECK(cudaMemcpy(h.data(), d.p, n * 4, cudaMemcpyDeviceToHost));
  return h;
}

template <int FAST> __global__ void __launch_bounds__(256) ct_matmul_0(I d0, I d1, I d2, const float* __restrict__ p0, const float* __restrict__ p1, float* __restrict__ out) {
  __shared__ float As[8][64];
  __shared__ float Bs[8][64];
  const int tid = threadIdx.x, tr = tid / 16, tc = tid % 16;
  const I row0 = (I)blockIdx.y * 64, col0 = (I)blockIdx.x * 64, Mx = (d0), Nx = (d2), Kx = (d1);
  float acc[4][4];
  for (int mm = 0; mm < 4; ++mm) for (int nn = 0; nn < 4; ++nn) acc[mm][nn] = 0.0f;
  for (I k0 = 0; k0 < Kx; k0 += 8) {
    const I kLen = Kx - k0 < 8 ? Kx - k0 : 8;
    for (int e = tid; e < 512; e += 256) {
      const int r = e / 8, c = e % 8;
      const I gi = row0 + r, kk = k0 + c;
      As[c][r] = (gi < Mx && c < kLen) ? p0[((gi) * (d1) + (kk))] : 0.0f;
    }
    for (int e = tid; e < 512; e += 256) {
      const int r = e / 64, c = e % 64;
      const I kk = k0 + r, gj = col0 + c;
      Bs[r][c] = (r < kLen && gj < Nx) ? p1[((kk) * (d2) + (gj))] : 0.0f;
    }
    __syncthreads();
    for (int kk = 0; kk < kLen; ++kk) {
      float a[4], b[4];
#pragma unroll
      for (int mm = 0; mm < 4; ++mm) a[mm] = As[kk][tr * 4 + mm];
#pragma unroll
      for (int nn = 0; nn < 4; ++nn) b[nn] = Bs[kk][tc * 4 + nn];
#pragma unroll
      for (int mm = 0; mm < 4; ++mm)
#pragma unroll
        for (int nn = 0; nn < 4; ++nn) acc[mm][nn] = __fadd_rn(acc[mm][nn], __fmul_rn(a[mm], b[nn]));
    }
    __syncthreads();
  }
  for (int mm = 0; mm < 4; ++mm)
    for (int nn = 0; nn < 4; ++nn) {
      const I gi = row0 + tr * 4 + mm, gj = col0 + tc * 4 + nn;
      if (gi < Mx && gj < Nx) {

        out[gi * Nx + gj] = acc[mm][nn];
      }
    }
}
static dim3 ct_matmul_0_grid(I d0, I d1, I d2) { return dim3((unsigned)(((d2) + 63) / 64), (unsigned)(((d0) + 63) / 64)); }
template <int FAST> __global__ void rg_softmax_0(I d0, I d1, const float* __restrict__ p0, float* __restrict__ out) {
  extern __shared__ float smem[];
  __shared__ float red[32];
  __shared__ float sc_m, sc_s;
  const I r = blockIdx.x;
  float* cursor = smem;
  float* s_e = cursor; cursor += (d1);
  float* scratch = cursor;
  // m
  for (I j = threadIdx.x; j < (d1); j += blockDim.x) {
    scratch[j] = p0[((r) * (d1) + (j))];
  }
  __syncthreads();
  { float m = -INFINITY; for (I j = threadIdx.x; j < (d1); j += blockDim.x) m = rf_minmax(m, scratch[j], true);
    m = rf_block_max(m); if (threadIdx.x == 0) red[0] = m; }
  __syncthreads();
  if (threadIdx.x == 0) {
    sc_m = red[0];
  }
  __syncthreads();
  // e
  for (I j = threadIdx.x; j < (d1); j += blockDim.x) {
    float v0 = __fsub_rn(p0[((r) * (d1) + (j))], sc_m);
    float v1 = FAST ? fast_exp(v0) : __double2float_rn(exp(static_cast<double>(v0)));
    s_e[j] = v1;
  }
  __syncthreads();
  // s
  for (I j = threadIdx.x; j < (d1); j += blockDim.x) {
    scratch[j] = s_e[(j)];
  }
  __syncthreads();
  if (threadIdx.x == 0) { float acc = 0.0f; for (I j = 0; j < (d1); ++j) acc = __fadd_rn(acc, scratch[j]); red[1] = acc; }
  __syncthreads();
  if (threadIdx.x == 0) {
    sc_s = red[1];
  }
  __syncthreads();
  // y
  for (I j = threadIdx.x; j < (d1); j += blockDim.x) {
    float v2 = __fdiv_rn(s_e[(j)], sc_s);
    out[r * (d1) + j] = v2;
  }
  __syncthreads();
}
