static I rg_softmax_0_inner(I d0, I d1) { return (d1); }
static I rg_softmax_0_smem(I d0, I d1) { return (d1) + std::max<I>({1LL, (d1), (d1)}); }
template <int FAST> __global__ void rg_layernorm_0(I d0, I d1, const float* __restrict__ p0, const float* __restrict__ p1, const float* __restrict__ p2, const float* __restrict__ p3, float* __restrict__ out) {
  extern __shared__ float smem[];
  __shared__ float red[32];
  __shared__ float sc_mean, sc_variance;
  const I r = blockIdx.x;
  float* cursor = smem;
  float* s_centered = cursor; cursor += (d1);
  float* scratch = cursor;
  // mean
  for (I j = threadIdx.x; j < (d1); j += blockDim.x) {
    scratch[j] = p0[((r) * (d1) + (j))];
  }
  __syncthreads();
  if (threadIdx.x == 0) { float acc = 0.0f; for (I j = 0; j < (d1); ++j) acc = __fadd_rn(acc, scratch[j]); red[0] = acc; }
  __syncthreads();
  if (threadIdx.x == 0) {
    float v0 = __fdiv_rn(red[0], __ll2float_rn(d1));
    sc_mean = v0;
  }
  __syncthreads();
  // centered
  for (I j = threadIdx.x; j < (d1); j += blockDim.x) {
    float v1 = __fsub_rn(p0[((r) * (d1) + (j))], sc_mean);
    s_centered[j] = v1;
  }
  __syncthreads();
  // variance
  for (I j = threadIdx.x; j < (d1); j += blockDim.x) {
    float v2 = __fmul_rn(s_centered[(j)], s_centered[(j)]);
    scratch[j] = v2;
  }
  __syncthreads();
  if (threadIdx.x == 0) { float acc = 0.0f; for (I j = 0; j < (d1); ++j) acc = __fadd_rn(acc, scratch[j]); red[1] = acc; }
  __syncthreads();
  if (threadIdx.x == 0) {
    float v3 = __fdiv_rn(red[1], __ll2float_rn(d1));
    sc_variance = v3;
  }
  __syncthreads();
  // y
  for (I j = threadIdx.x; j < (d1); j += blockDim.x) {
    float v4 = __fadd_rn(sc_variance, p3[(0LL)]);
    float v5 = __fsqrt_rn(v4);
    float v6 = __fdiv_rn(s_centered[(j)], v5);
    float v7 = __fmul_rn(v6, p1[(j)]);
    float v8 = __fadd_rn(v7, p2[(j)]);
    out[r * (d1) + j] = v8;
  }
  __syncthreads();
}
