static dim3 ct_mlp_0_grid(I d0, I d1, I d2, I d3) { return dim3((unsigned)(((d2) + 63) / 64), (unsigned)(((d0) + 63) / 64)); }
template <int FAST> __global__ void rg_mlp_1(I d0, I d1, I d2, I d3, const float* __restrict__ p0, const float* __restrict__ p1, const float* __restrict__ p2, const float* __restrict__ p3, const float* __restrict__ p4, const float* __restrict__ p5, float* __restrict__ out) {
  extern __shared__ float smem[];
  __shared__ float red[32];
  const I r = blockIdx.x;
  float* cursor = smem;
  float* scratch = cursor;
  // g
  for (I j = threadIdx.x; j < (d2); j += blockDim.x) {
    float v0 = __fmul_rn(__uint_as_float(0x3f000000u), p5[((r) * (d2) + (j))]);
    float v1 = __fmul_rn(__uint_as_float(0x3d372713u), p5[((r) * (d2) + (j))]);
    float v2 = __fmul_rn(v1, p5[((r) * (d2) + (j))]);
    float v3 = __fmul_rn(v2, p5[((r) * (d2) + (j))]);
    float v4 = __fadd_rn(p5[((r) * (d2) + (j))], v3);
    float v5 = __fmul_rn(__uint_as_float(0x3f4c422au), v4);
    float v6 = FAST ? fast_tanh(v5) : __double2float_rn(tanh(static_cast<double>(v5)));
    float v7 = __fadd_rn(__uint_as_float(0x3f800000u), v6);
    float v8 = __fmul_rn(v0, v7);
    out[r * (d2) + j] = v8;
  }
  __syncthreads();
}
