static I rg_mlp_1_smem(I d0, I d1, I d2, I d3) { return std::max<I>({1LL}); }
template <int FAST> __global__ void __launch_bounds__(256) ct_mlp_2(I d0, I d1, I d2, I d3, const float* __restrict__ p0, const float* __restrict__ p1, const float* __restrict__ p2, const float* __restrict__ p3, const float* __restrict__ p4, const float* __restrict__ p5, const float* __restrict__ p6, float* __restrict__ out) {
  __shared__ float As[8][64];
  __shared__ float Bs[8][64];
  const int tid = threadIdx.x, tr = tid / 16, tc = tid % 16;
  const I row0 = (I)blockIdx.y * 64, col0 = (I)blockIdx.x * 64, Mx = (d0), Nx = (d3), Kx = (d2);
  float acc[4][4];
  for (int mm = 0; mm < 4; ++mm) for (int nn = 0; nn < 4; ++nn) acc[mm][nn] = 0.0f;
  for (I k0 = 0; k0 < Kx; k0 += 8) {
    const I kLen = Kx - k0 < 8 ? Kx - k0 : 8;
    for (int e = tid; e < 512; e += 256) {
      const int r = e / 8, c = e % 8;
      const I gi = row0 + r, kk = k0 + c;
      As[c][r] = (gi < Mx && c < kLen) ? p6[((gi) * (d2) + (kk))] : 0.0f;
    }
    for (int e = tid; e < 512; e += 256) {
      const int r = e / 64, c = e % 64;
      const I kk = k0 + r, gj = col0 + c;
      Bs[r][c] = (r < kLen && gj < Nx) ? p3[((kk) * (d3) + (gj))] : 0.0f;
    }
    __syncthreads();
    for (int kk = 0; kk < kLen; ++kk) {
      float a[4], b[4];
#pragma unroll
      for (int mm = 0; mm < 4; ++mm) a[mm] = As[kk][tr * 4 + mm];
#pragma unroll
      for (int nn = 0; nn < 4; ++nn) b[nn] = Bs[kk][tc * 4 + nn];
#pragma unroll
      for (int mm = 0; mm < 4; ++mm)
#pragma unroll
        for (int nn = 0; nn < 4; ++nn) acc[mm][nn] = __fadd_rn(acc[mm][nn], __fmul_rn(a[mm], b[nn]));
    }
    __syncthreads();
  }
  for (int mm = 0; mm < 4; ++mm)
    for (int nn = 0; nn < 4; ++nn) {
      const I gi = row0 + tr * 4 + mm, gj = col0 + tc * 4 + nn;
      if (gi < Mx && gj < Nx) {
        float e0 = __fadd_rn(acc[mm][nn], p4[(gj)]);
        out[gi * Nx + gj] = e0;
      }
    }
}
